<script setup>
import {ref,computed,onMounted} from 'vue'
import {api,post,references,portLabel,formatTimestamp} from './quotationApi'
const props=defineProps({initialId:{type:String,default:null}})
const emit=defineEmits(['drafts'])
const refs=ref({ports:[],suppliers:[],source_series:[]}),history=ref([]),file=ref(null),preview=ref(null),selected=ref([])
const busy=ref(false),error=ref(''),message=ref(''),page=ref(1)
const options=ref({origin_port_id:'',source_series_id:'',currency:'',validity_basis:'',service_kind:'',service_key:''})
const currencies=ref([])
const visibleRows=computed(()=>preview.value?.rows.slice((page.value-1)*50,page.value*50)||[])
async function load(){try{const [r,defaults,imports]=await Promise.all([references(),api('/api/manual-drafts/defaults'),api('/api/excel/imports')]);refs.value=r;options.value.origin_port_id=defaults.data.origin_port_id;currencies.value=defaults.currencies;history.value=imports.items}catch(e){error.value=e.message}}
function choose(event){file.value=event.target.files[0]||null;preview.value=null;error.value='';message.value=''}
function applyPreview(data){preview.value=data;page.value=1;selected.value=data.status==='committed'?data.selection:data.rows.filter(r=>r.importable).map(r=>r.id)}
async function upload(){if(!file.value||busy.value)return;busy.value=true;error.value='';message.value='';try{if(file.value.size>20*1024*1024)throw new Error('文件不能超过20MB');const params=new URLSearchParams({filename:file.value.name,options_json:JSON.stringify(options.value)});const result=await api('/api/excel/imports/preview?'+params,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file.value});applyPreview(result);if(result.duplicate)message.value='同一原件已有批次，已打开原预览；不会重复生成草稿。本次补充条件未覆盖原批次。';history.value=(await api('/api/excel/imports')).items}catch(e){error.value=e.message}finally{busy.value=false}}
async function open(id){busy.value=true;error.value='';message.value='';try{applyPreview(await api('/api/excel/imports/'+id))}catch(e){error.value=e.message}finally{busy.value=false}}
async function commit(){if(busy.value||!selected.value.length)return;busy.value=true;error.value='';try{const result=await post(`/api/excel/imports/${preview.value.id}/commit`,{row_ids:selected.value});preview.value.status='committed';message.value=`已生成${result.created}条未审批草稿。请进入草稿逐项校对，未写入正式报价。`;history.value=(await api('/api/excel/imports')).items}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{await load();if(props.initialId)await open(props.initialId)})
</script>
<template><section class="quotes-panel"><div class="catalog-heading"><div><h2>Excel报价导入</h2><p>按18列模板读取，先预览和选择，再生成未审批草稿。</p></div><a class="small-button" href="/api/excel/template" download>下载填写模板</a></div>
  <div class="quote-banner">支持xls、xlsx，每个文件不超过20MB。空价格目录不生成报价；不执行公式。PDF、图片请使用“上传原件与提取报价”。</div>
  <form class="catalog-form quote-form" @submit.prevent="upload"><fieldset :disabled="busy"><label>Excel报价文件<input type="file" accept=".xls,.xsl,.xlsx" @change="choose"></label><h3>原文件缺失时的补充条件</h3><p class="catalog-note">以下条件只填补原文件空白，不覆盖文件中已有值；导入后仍须核对起运港并确认零价及适用条件。</p><div class="form-fields">
  <label>默认起运港<select v-model="options.origin_port_id"><option v-for="p in refs.ports.filter(p=>p.active)" :key="p.id" :value="p.id">{{portLabel(p)}}</option></select></label>
  <label>默认报价来源<select v-model="options.source_series_id"><option value="">留空，导入后补齐</option><option v-for="s in refs.source_series.filter(s=>s.active)" :key="s.id" :value="s.id">{{refs.suppliers.find(p=>p.id===s.supplier_id)?.name}} · {{s.name}}</option></select></label>
  <label>默认币种<select v-model="options.currency"><option value="">留空，导入后补齐</option><option v-for="c in currencies" :key="c">{{c}}</option></select></label>
  <label>有效期依据<select v-model="options.validity_basis"><option value="">不推定，导入后核对</option><option value="ETD">明确为ETD开船日</option><option value="other">其他依据</option></select></label>
  <label>服务类型<select v-model="options.service_kind"><option value="">不推定，导入后核对</option><option value="direct">直达</option><option value="transshipment">中转</option></select></label><label>服务标识<input v-model="options.service_key" maxlength="160" placeholder="供应商服务名称；可留空"></label></div>
  <div class="form-actions"><button class="small-button primary" :disabled="!file" type="submit">{{busy?'处理中…':'预览报价文件'}}</button><button class="small-button" type="button" @click="emit('drafts')">返回报价草稿</button></div></fieldset></form>
  <p v-if="error" class="feedback error" role="alert">{{error}}</p><p v-if="message" class="feedback success" role="status">{{message}}</p>
  <section v-if="preview"><h3>{{preview.filename}} · {{preview.status==='committed'?'已生成草稿（以下为原始导入快照）':'导入预览'}}</h3><p v-if="preview.file_id"><a :href="`/api/uploads/files/${preview.file_id}/original`" download>下载原件核对</a></p><p class="catalog-note">共{{preview.counts.total}}行报价，可保存{{preview.counts.importable}}行，失败{{preview.counts.failed}}行，待补齐{{preview.counts.pending}}行；另跳过{{preview.skipped_empty_prices}}行空价格目录。</p>
  <p v-for="item in preview.sheet_errors" :key="item.sheet" class="feedback error">{{item.sheet}}：{{item.message}}</p><p v-if="!preview.rows.length" class="quote-banner">没有填写箱型价格的报价。请在模板中填入价格后重新上传。</p>
  <div class="form-actions" v-if="preview.status!=='committed'"><button class="small-button" :disabled="busy" @click="selected=preview.rows.filter(r=>r.importable).map(r=>r.id)">选择全部可导入行</button><button class="small-button" :disabled="busy" @click="selected=[]">清空选择</button><button class="small-button primary" :disabled="busy||!selected.length" @click="commit">将选中{{selected.length}}行保存为草稿</button></div><button v-else class="small-button primary" @click="emit('drafts')">进入草稿校对</button>
  <div class="catalog-table import-table"><table><thead><tr><th>选择</th><th>原表位置</th><th>目的港／船公司</th><th>箱价／有效期</th><th>检查结果与原文</th></tr></thead><tbody><tr v-for="r in visibleRows" :key="r.id"><td><input type="checkbox" :value="r.id" v-model="selected" :disabled="busy||!r.importable||preview.status==='committed'" :aria-label="`选择${r.sheet}第${r.row}行`"></td><td>{{r.sheet}}<br>第{{r.row}}行</td><td>{{r.effective['国家中文名']}} · {{r.raw['中文港口名']||r.raw['英文港口名']}}<br>{{r.raw['船公司']||'船公司待补齐'}}</td><td>20GP {{r.data.prices['20GP']||'缺价'}}<br>40GP {{r.data.prices['40GP']||'缺价'}}<br>40HQ {{r.data.prices['40HQ']||'缺价'}}<br>{{r.data.currency||'币种待补齐'}}<br>{{r.data.valid_from||'起日待补齐'}} ～ {{r.data.valid_to||'止日待补齐'}}</td><td><b>{{!r.importable?'失败，不可导入':r.issues.length?'待补齐，可存草稿':'字段检查通过，未审批'}}</b><ul><li v-for="(msg,i) in [...r.fatal_errors,...r.mapping_notes,...r.issues.map(x=>x.message)]" :key="i">{{msg}}</li></ul><details><summary>查看原始行</summary><dl><template v-for="(value,label) in r.raw" :key="label"><dt>{{label}}</dt><dd>{{value||'（空）'}}</dd></template></dl></details></td></tr></tbody></table></div>
  <div class="pagination" v-if="preview.rows.length>50"><button class="small-button" :disabled="page<=1" @click="page--">上一页</button><span>第{{page}}／{{Math.ceil(preview.rows.length/50)}}页</span><button class="small-button" :disabled="page*50>=preview.rows.length" @click="page++">下一页</button></div></section>
  <section class="import-history"><h3>已保存的导入批次</h3><p v-if="!history.length">暂无导入批次。</p><article v-for="item in history" :key="item.id"><div>{{item.original_name}}<small>{{item.status==='committed'?`已生成${item.committed_count}条草稿`:'预览待确认'}} · {{formatTimestamp(item.created_at)}}</small></div><button class="small-button" :disabled="busy" @click="open(item.id)">查看批次</button></article></section>
</section></template>
